(() => {
 'use strict';
 if(!document.documentElement.dataset.nkRouteDocument&&!(window!==window.parent&&new URL(location.href).searchParams.has('nk_frame'))&&!new URL(location.href).searchParams.has('nk_direct'))return;
 const desktop=matchMedia('(min-width: 1024px)');
 const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const main=document.querySelector('main');if(!main)return;
 const sectionNames={'float-playground':'Find your Float',home:'The entrance',possibilities:'Ancient roots',about:'The foundation',slabs:'Your Slabs',payday:'Payday rules',card:'Your card',numbers:'What matters', 'how-it-works':'Your path',toolkit:'Your toolkit',features:'Your toolkit','chapter-7':'What matters','chapter-8':'Our nature','chapter-16':'Your next chapter', 'dashboard':'Your camp',principles:'Set in stone','field-notes':'Field notes',faq:'Good questions',chapters:'More paths'};
 const sections=Array.from(main.children).filter(e=>e.matches('section,.feature-stack')).flatMap(e=>e.matches('.feature-stack')?Array.from(e.querySelectorAll('.feature')):[e]);
 const reveal=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('era-visible');reveal.unobserve(e.target)}}),{threshold:.12});
 document.querySelectorAll('.foundation-grid article,.scene-three article,.slab-purpose-grid article,.network-map>div,.architecture-flow>.stone-frame,.product-feature-row,.process-row,.chapter-link,.note,.page-hero,.aurum-intro,.statue-bottom>div,.dunes-copy,.dunes-aside,.section-label,.page-end,.recovery-row>div,.statue-visual,.dunes-orbit').forEach((e,i)=>{e.classList.add('era-reveal');e.style.setProperty('--reveal-delay',(i%3)*65+'ms');reveal.observe(e)});
 if(document.body.classList.contains('dashboard-body'))return;
 const drawer=document.createElement('aside');drawer.className='section-map';drawer.id='section-map';drawer.inert=true;drawer.setAttribute('aria-label','Sections on this page');
 const page=location.pathname.replace(/\.html$/,'').replace(/\/$/,'');
 const pageChapters={foundation:['The foundation','The short film','Account, card & recovery','How Card Desk works','Networks & routes','Your account'],product:['One account','Noklith in motion','Everyday possibilities','Your account'],slabs:['Give it a place','Four spaces, your way'],architecture:['Meet Noklith','Beneath the surface','Every layer has a role'],ownership:['Your keys first','A clearer kind of control','Recovery, on your terms'],photography:['Photography & sources','Image credits']};
 const chapters=pageChapters[page.split('/').pop()];
 const items=sections.map((s,i)=>{if(!s.id)s.id='chapter-'+(i+1);let label=chapters?.[i]||sectionNames[s.id]||s.querySelector('h2,h1')?.innerText||s.getAttribute('aria-label')||'A closer look';label=label.replace(/\s+/g,' ').trim();if(label.length>38)label=label.slice(0,36).replace(/\s\S*$/,'').replace(/[.,:;]+$/,'')+'…';return{id:s.id,label,element:s}});
 drawer.innerHTML='<div class="map-heading"><img src="/assets/noklith-emblem.webp" width="46" height="46" alt=""><div><span>ON THIS PAGE</span><p>Choose a chapter.</p></div><button aria-label="Close section navigation">×</button></div><nav aria-label="Page sections">'+items.map((s,i)=>'<a href="#'+s.id+'"><small>'+String(i+1).padStart(2,'0')+'</small><span>'+s.label+'</span><b>↗</b></a>').join('')+'</nav><a class="map-app" href="/dashboard.html">Return to your camp <span>↗</span></a>';
 const button=document.createElement('button');button.className='section-map-toggle';button.setAttribute('aria-label','Open section navigation');button.setAttribute('aria-controls','section-map');button.setAttribute('aria-expanded','false');button.innerHTML='<svg class=crack-menu viewBox="0 0 40 40" aria-hidden="true"><g class=crack-bars><path d="M8 11L31 10L32 13L7 14Z"/><path d="M7 19L33 18L32 22L8 23Z"/><path d="M9 28L31 27L33 30L7 31Z"/></g><path class=crack-line d="M23 5L18 13L23 17L17 23L21 27L15 35M23 17L29 16M17 23L11 22"/></svg>';
 const shade=document.createElement('div');shade.className='map-shade';
 document.body.append(shade,drawer,button);let focusBefore;
 function close(restore=true){if(window!==window.top)parent.postMessage({type:'nk-drawer',open:false},location.origin);document.body.classList.remove('map-open');document.dispatchEvent(new Event('noklith:overlaychange'));drawer.setAttribute('inert','');main.removeAttribute('inert');document.querySelector('.site-header')?.removeAttribute('inert');button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Open section navigation');if(restore)focusBefore?.focus()}
 function open(){if(!desktop.matches)return;if(window!==window.top)parent.postMessage({type:'nk-drawer',open:true},location.origin);focusBefore=document.activeElement;document.body.classList.add('map-open');document.dispatchEvent(new Event('noklith:overlaychange'));drawer.removeAttribute('inert');main.setAttribute('inert','');document.querySelector('.site-header')?.setAttribute('inert','');button.setAttribute('aria-expanded','true');button.setAttribute('aria-label','Close section navigation');requestAnimationFrame(()=>drawer.querySelector('button').focus())}
 button.onclick=()=>document.body.classList.contains('map-open')?close():open();drawer.querySelector('button').onclick=close;shade.onclick=close;
 document.addEventListener('keydown',e=>{if(!document.body.classList.contains('map-open'))return;if(e.key==='Escape')close();if(e.key==='Tab'){const n=[...drawer.querySelectorAll('a,button')],first=n[0],last=n.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
 function scrollToSection(id){const el=document.getElementById(id);if(!el)return;let y=el.getBoundingClientRect().top+scrollY;const stack=el.closest('.feature-stack.is-pinned');if(stack){const i=[...stack.querySelectorAll('.feature')].indexOf(el);y=stack.getBoundingClientRect().top+scrollY+(stack.offsetHeight-innerHeight)*(i===0?0:i===1?.36:.7)}window.scrollTo({top:y,behavior:reduce?'instant':'smooth'})}
 drawer.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();const id=a.hash.slice(1);close();history.replaceState(null,'',a.hash);scrollToSection(id)}));
 const links=[...drawer.querySelectorAll('nav a')];
 const visible=()=>{if(!desktop.matches){button.classList.remove('map-available');if(document.body.classList.contains('map-open'))close(false);return}button.classList.toggle('map-available',scrollY>Math.min(300,innerHeight*.4));let current=items[0];for(const item of items){const r=item.element.getBoundingClientRect();if(r.top<innerHeight*.45)current=item}const activeFeature=document.querySelector('.feature.is-active');if(activeFeature&&activeFeature.getBoundingClientRect().top<innerHeight*.5&&activeFeature.getBoundingClientRect().bottom>innerHeight*.5)current=items.find(i=>i.id===activeFeature.id)||current;links.forEach(a=>{const on=a.hash==='#'+current.id;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')});button.style.setProperty('--map-progress',String(scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight)))};
 let frame=0;const schedule=()=>{if(!frame)frame=requestAnimationFrame(()=>{frame=0;visible()})};addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);desktop.addEventListener('change',schedule);visible();
 document.addEventListener('noklith:ready',()=>{if(location.hash&&document.getElementById(location.hash.slice(1))?.classList.contains('feature'))scrollToSection(location.hash.slice(1))});
})();
